// js
const entry = get(ctx, 'entry', {});
const terms = ctx.subject.employment.terms;
const rate = get(terms, 'rate', {});
const amount = Number(get(rate, 'amount', 0));
const unit = get(rate, 'unit', 'MONTHLY');
const fixed = Number(get(get(terms, 'allowances.FIXED_ALLOWANCE', {}), 'amount', 0));
const from = month_start(ctx.run.salary_coverage.from);
const to = month_end(ctx.run.salary_coverage.from);
const offDays = get(ctx.subject, 'employer.payment_schedule.non_working_weekdays', [0, 6]);
let workingDays = 0;
for (let day = from; day <= to; day = add_days(day, 1)) {
	if (!offDays.includes(weekday(day))) workingDays = workingDays + 1;
}
const weekDays = Math.max(1, 7 - offDays.length);
const contractDays = Number(get(terms, 'normal_days_per_week', 0)) || weekDays;
const days =
	workingDays > 0
		? (workingDays * contractDays) / weekDays
		: ctx.lookup.fallback_working_days;
const hoursPerDay =
	Number(get(terms, 'normal_hours_per_day', 0)) || ctx.lookup.normal_hours_per_day;
const hoursPerMonth = days * hoursPerDay;
const monthly =
	unit === 'HOURLY'
		? amount * hoursPerMonth
		: unit === 'DAILY'
			? amount * days
			: amount;
const hourly = (monthly + fixed) / hoursPerMonth;
return hourly * Number(get(entry, 'quantity', 0)) * ctx.lookup.factor;

